"""Generate the vendor stand-ins for zoo/node.py: gland_m12.step, antenna.step
and panel.step. Each is one coloured solid, as a purchased part's STEP file
would be. Regenerated by a test so the files never drift from this generator.
"""
from pathlib import Path

from build123d import (
    Align,
    Axis,
    Box,
    Color,
    Cylinder,
    Location,
    Plane,
    Polyline,
    RegularPolygon,
    Solid,
    Sphere,
    export_step,
    extrude,
    make_face,
    revolve,
)

HERE = Path(__file__).parent
UP = (Align.CENTER, Align.CENTER, Align.MIN)


def gland_m12() -> Solid:
    """An M12 cable gland along Z: the thread below the hex flange (z < 0), a domed cap nut
    with the cable hole on top. The thread is the largest cylindrical face, the flange's
    underside the face that seats on the wall."""
    thread = Cylinder(6, 10, align=(Align.CENTER, Align.CENTER, Align.MAX))
    flange = extrude(RegularPolygon(11, 6), amount=5)
    cap = revolve(Plane.XZ * make_face(Polyline(
        (0, 5), (9, 5), (9, 10), (8, 13), (5.5, 16), (0, 16), close=True)), Axis.Z, 360)
    hole = Cylinder(3, 12, align=UP).moved(Location((0, 0, 6)))
    s = (thread + flange + cap - hole).solid()
    s.label, s.color = "gland_m12", Color(0.35, 0.35, 0.38)
    return s


def antenna() -> Solid:
    """A stub antenna along Z: an SMA hex nut at the base, a rod with a rounded tip."""
    nut = extrude(RegularPolygon(7, 6), amount=6)
    rod = Cylinder(4.5, 60, align=UP).moved(Location((0, 0, 6)))
    tip = Sphere(4.5).moved(Location((0, 0, 66)))
    s = (nut + rod + tip).solid()
    s.label, s.color = "antenna", Color(0.1, 0.1, 0.1)
    return s


def panel() -> Solid:
    """A solar panel: a 150 x 100 framed plate with the cells raised inside the frame, its
    bottom at z = 0, and the junction box on the underside."""
    frame = Box(150, 100, 5, align=UP)
    cells = Box(140, 90, 1.5, align=UP).moved(Location((0, 0, 5)))
    box = Box(32, 22, 8, align=(Align.CENTER, Align.CENTER, Align.MAX)).moved(Location((0, 36, 0)))  # up the slope, clear of the lid
    s = (frame + cells + box).solid()
    s.label, s.color = "panel", Color(0.12, 0.2, 0.45)
    return s


GENERATORS = {"gland_m12.step": gland_m12, "antenna.step": antenna, "panel.step": panel}


def write_all(out_dir: Path = HERE) -> list[Path]:
    paths = []
    for name, fn in GENERATORS.items():
        path = out_dir / name
        export_step(fn(), path, timestamp="2026-09-04T00:00:00")
        paths.append(path)
    return paths


if __name__ == "__main__":
    for p in write_all():
        print(f"wrote {p} ({p.stat().st_size} bytes)")
